import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.DMvgf4hZ.js";const k=JSON.parse('{"title":"插件、技能与提供方","description":"","frontmatter":{},"headers":[],"relativePath":"development/plugins.md","filePath":"development/plugins.md","lastUpdated":1794884041000}'),i={name:"development/plugins.md"};function d(l,t,n,r,h,p){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="插件、技能与提供方" tabindex="-1">插件、技能与提供方 <a class="header-anchor" href="#插件、技能与提供方" aria-label="Permalink to &quot;插件、技能与提供方&quot;">​</a></h1><h2 id="通过网页唤起桌面安装插件" tabindex="-1">通过网页唤起桌面安装插件 <a class="header-anchor" href="#通过网页唤起桌面安装插件" aria-label="Permalink to &quot;通过网页唤起桌面安装插件&quot;">​</a></h2><p>安装桌面客户端后，网页可通过 <code>toonflow://install</code> 请求安装插件。应用会先展示类型、文件名和下载地址，用户确认后再下载与安装。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> link</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;toonflow://install&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">link.searchParams.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;type&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;node&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">link.searchParams.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;url&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://example.com/plugins/exampleNode.umd.js&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.location.href </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> link.href</span></span></code></pre></div><table tabindex="0"><thead><tr><th><code>type</code></th><th>文件格式</th><th>安装位置</th></tr></thead><tbody><tr><td><code>node</code></td><td><code>.umd.js</code></td><td><code>data/nodes/</code></td></tr><tr><td><code>tool</code></td><td><code>.tool.js</code></td><td><code>data/tools/</code></td></tr><tr><td><code>skill</code></td><td><code>SKILL.md</code>、<code>.zip</code>、<code>.tar</code>、<code>.tar.gz</code>、<code>.tgz</code></td><td><code>data/skills/&lt;name&gt;/</code></td></tr><tr><td><code>provider</code></td><td>媒体提供方 <code>.ts</code></td><td><code>data/providers/</code></td></tr></tbody></table><p>下载地址须为 HTTP/HTTPS，文件名来自 URL 路径。同名节点、工具和技能在版本更高时允许更新；覆盖同版本或降级需在开发者选项中使用强制安装，提供方不覆盖同名项。</p><p>普通插件与技能包最多 20 MB，技能解压后也受此限制；提供方最多 2 MB。技能包支持 ZIP 和 TAR，须包含带有 <code>name</code>、<code>description</code> frontmatter 的 <code>SKILL.md</code>，附属资源放在其所在目录内。TAR 包使用普通 USTAR 格式，不包含链接及 PAX/GNU 扩展条目。</p><p>Windows 安装器负责注册协议；macOS 需要将应用放入 <code>/Applications</code> 或 <code>~/Applications</code>。普通浏览器开发模式不注册桌面协议。</p><h2 id="插件开发工具" tabindex="-1">插件开发工具 <a class="header-anchor" href="#插件开发工具" aria-label="Permalink to &quot;插件开发工具&quot;">​</a></h2><p>插件开发工具位于 <code>packages/tools/pluginDeveloper</code>，作为工作区子包随默认工具构建和内置，产物为 <code>build/tools/pluginDeveloper.tool.js</code>，开发构建同步到 <code>data/tools/</code>。SDK 下载、缓存和插件构建由工具负责，主程序只提供本机权限校验及安装、刷新、上传桥接。工具私有资源在卸载时一并清理。</p><p>安装后可在插件市场或助手中调用，用于创建骨架、本地构建、上传与刷新插件。</p><h2 id="从零开发一个插件" tabindex="-1">从零开发一个插件 <a class="header-anchor" href="#从零开发一个插件" aria-label="Permalink to &quot;从零开发一个插件&quot;">​</a></h2><p>本节讲的是<strong>安装契约与协议</strong>（安装格式、大小限制、<code>toonflow://install</code> 唤起、提供方适配）。如果你要从零写一个工具、节点或技能并发布，请看独立的「插件开发」分区：</p><ul><li><a href="/toonflow/plugins/">插件开发总览</a> —— 三类扩展怎么选、目录与构建环境、命名与版本、安装调试、运行边界。</li><li><a href="/toonflow/plugins/tools.html">Tools 工具插件开发</a> —— <code>createToolConfig</code> 构建元数据、<code>ToolDefinition</code> 契约、宿主上下文、FFmpeg、可选消息界面。</li><li><a href="/toonflow/plugins/nodes.html">Nodes 节点插件开发</a> —— <code>createNodeConfig</code>、<code>defineOptions</code> 端口、<code>useNode</code> 状态、文件与媒体持久化、节点操作。</li><li><a href="/toonflow/plugins/skill.html">Skill 技能插件开发</a> —— <code>SKILL.md</code> 字段、最小示例、<code>skillOperator</code> 调试、打包安装。</li><li><a href="/toonflow/plugins/checklist.html">交付前检查</a> 与 <a href="/toonflow/plugins/publish.html">发布插件</a>。</li></ul><h2 id="各扩展类型的入口" tabindex="-1">各扩展类型的入口 <a class="header-anchor" href="#各扩展类型的入口" aria-label="Permalink to &quot;各扩展类型的入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>扩展类型</th><th>脚手架 / 实现</th><th>说明</th></tr></thead><tbody><tr><td>节点</td><td><a href="https://github.com/dolfly/toonflow/blob/master/packages/nodeScaffold/readme.md" target="_blank" rel="noreferrer">packages/nodeScaffold</a></td><td>画布交互组件、端口与节点操作。</td></tr><tr><td>工具</td><td><a href="https://github.com/dolfly/toonflow/blob/master/packages/toolScaffold/readme.md" target="_blank" rel="noreferrer">packages/toolScaffold</a></td><td>Agent 可调用的能力，可带交互 UI。</td></tr><tr><td>技能</td><td><a href="https://github.com/dolfly/toonflow/tree/master/packages/skills" target="_blank" rel="noreferrer">packages/skills</a></td><td><code>SKILL.md</code> 描述的创作流程与方法。</td></tr><tr><td>提供方</td><td><a href="https://github.com/dolfly/toonflow/tree/master/packages/providers/src" target="_blank" rel="noreferrer">packages/providers/src</a></td><td>模型列表、请求参数与媒体返回结果适配。</td></tr></tbody></table><p>节点与工具的配置表单统一使用 <code>@form-create/element-ui</code> 的规则；有必填项未填写时，配置按钮会显示红点。工具只接收自身配置，宿主不向工具直接传递完整应用设置。</p><p>媒体接口包含图片、视频和音频的扩展类型，实际能力由各提供方实现。技能既可以全局安装，也可以放在当前工作区的 <code>skill/</code> 目录，同名时优先使用工作区版本。</p><h2 id="mcp-接入" tabindex="-1">MCP 接入 <a class="header-anchor" href="#mcp-接入" aria-label="Permalink to &quot;MCP 接入&quot;">​</a></h2><p>需要从外部 Coding 工具操作 Toonflow 时，在“设置 → MCP”开启服务并复制客户端配置，支持 HTTP 与 stdio 连接。画布和节点等界面操作需要保持 Toonflow 窗口或网页打开。</p><p>完整说明见 <a href="https://github.com/dolfly/toonflow/blob/master/packages/mcp/README.md" target="_blank" rel="noreferrer">packages/mcp/README.md</a>。</p>`,21)])])}const g=e(i,[["render",d]]);export{k as __pageData,g as default};
